<?php
require_once __DIR__.'/includes/v2.php';$user=require_login();$admin=$user['role']==='admin';$uid=(int)$user['user_id'];$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){
 v2_require_post();if(!$admin)v2_error('Admin only.',403);
 try{
  $action=$_POST['action']??'';
  if($action==='register'){
   $name=trim($_POST['unit_name']??'');$type=trim($_POST['vehicle_type']??'');$plate=trim($_POST['plate_number']??'');if(!$name||!$type||strlen($name)>120||strlen($type)>80||strlen($plate)>40)throw new RuntimeException('Invalid vehicle data.');
   db()->prepare('INSERT INTO vehicle(unit_name,vehicle_type,plate_number,status) VALUES (?,?,?,?)')->execute([$name,$type,$plate,'available']);v2_event($uid,'vehicle_registry','Vehicle registered',$name);redirect('vehicles.php');
  }
  if($action==='vehicle_status'){
   $id=(int)($_POST['vehicle_id']??0);$status=$_POST['status']??'';if(!in_array($status,['available','in_use','maintenance','out_of_service'],true))throw new RuntimeException('Invalid status.');
   db()->prepare('UPDATE vehicle SET status=? WHERE vehicle_id=?')->execute([$status,$id]);v2_event($uid,'vehicle_status','Vehicle status changed','Vehicle #'.$id.' · '.$status);redirect('vehicles.php');
  }
  if($action==='assign'){
   $id=(int)($_POST['vehicle_id']??0);$person=(int)($_POST['person_id']??0);$q=db()->prepare("SELECT user_id FROM user WHERE user_id=? AND status='active'");$q->execute([$person]);if(!$q->fetch())throw new RuntimeException('Select an active user.');
   db()->beginTransaction();$q=db()->prepare('SELECT assignment_id FROM vehicle_assignment WHERE vehicle_id=? AND returned_at IS NULL FOR UPDATE');$q->execute([$id]);if($q->fetch())throw new RuntimeException('Vehicle already assigned.');
   db()->prepare('INSERT INTO vehicle_assignment(vehicle_id,assigned_user_id,assigned_by) VALUES (?,?,?)')->execute([$id,$person,$uid]);v2_event($uid,'vehicle_assignment','Vehicle assigned','Vehicle #'.$id.' · User #'.$person);db()->commit();redirect('vehicles.php');
  }
  if($action==='release'){
   $id=(int)($_POST['assignment_id']??0);$q=db()->prepare('UPDATE vehicle_assignment SET returned_at=NOW() WHERE assignment_id=? AND returned_at IS NULL');$q->execute([$id]);if(!$q->rowCount())throw new RuntimeException('Assignment already closed.');v2_event($uid,'vehicle_assignment','Vehicle returned','Assignment #'.$id);redirect('vehicles.php');
  }
  if($action==='fuel_review'){
   $id=(int)($_POST['fuel_id']??0);$decision=$_POST['decision']??'';if(!in_array($decision,['approved','rejected'],true))throw new RuntimeException('Invalid fuel decision.');
   $q=db()->prepare("UPDATE fuel_approval SET status=?,approved_by=?,reviewed_at=NOW() WHERE fuel_id=? AND status='pending'");$q->execute([$decision,$uid,$id]);if(!$q->rowCount())throw new RuntimeException('Fuel record already reviewed.');v2_event($uid,'vehicle_fuel','Fuel transaction '.$decision,'Fuel #'.$id);redirect('vehicles.php');
  }
  if($action==='maintenance_update'){
   $id=(int)($_POST['maintenance_id']??0);$status=$_POST['status']??'';$notes=trim($_POST['resolution_notes']??'');$cost=(float)($_POST['cost_php']??0);$date=$_POST['service_date']??null;$next=$_POST['next_service_date']??null;
   if(!in_array($status,['reported','in_progress','resolved'],true)||$cost<0||$cost>100000000||strlen($notes)>3000)throw new RuntimeException('Invalid maintenance update.');
   $q=db()->prepare('UPDATE vehicle_maintenance SET status=? WHERE maintenance_id=?');$q->execute([$status,$id]);db()->prepare('INSERT INTO maintenance_detail(maintenance_id,cost_php,service_date,next_service_date,resolution_notes) VALUES (?,?,?,?,?) ON DUPLICATE KEY UPDATE cost_php=VALUES(cost_php),service_date=VALUES(service_date),next_service_date=VALUES(next_service_date),resolution_notes=VALUES(resolution_notes)')->execute([$id,$cost,$date?:null,$next?:null,$notes]);v2_event($uid,'vehicle_maintenance','Maintenance updated','Maintenance #'.$id.' · '.$status);redirect('vehicles.php');
  }
  $vehicle=(int)($_POST['vehicle_id']??0);$q=db()->prepare('SELECT * FROM vehicle WHERE vehicle_id=?');$q->execute([$vehicle]);$v=$q->fetch();if(!$v)throw new RuntimeException('Vehicle not found.');
  if($action==='fuel'){
   $liters=(float)($_POST['liters']??0);$price=(float)($_POST['price']??0);$station=trim($_POST['station']??'');$odometer=trim($_POST['odometer']??'');
   if($liters<=0||$liters>10000||$price<0||$price>100000||strlen($station)>120||($odometer!==''&&(!is_numeric($odometer)||(float)$odometer<0)))throw new RuntimeException('Invalid fuel transaction.');
   db()->prepare('INSERT INTO fuel_log(vehicle_id,recorded_by,liters,price_per_liter,odometer_km,station,fueled_at) VALUES (?,?,?,?,?,?,NOW())')->execute([$vehicle,$uid,$liters,$price,$odometer===''?null:(float)$odometer,$station]);$fuelId=(int)db()->lastInsertId();$receipt=null;
   if(isset($_FILES['receipt'])&&$_FILES['receipt']['error']!==UPLOAD_ERR_NO_FILE){$file=$_FILES['receipt'];if($file['error']!==UPLOAD_ERR_OK||$file['size']>3000000)throw new RuntimeException('Receipt must be under 3MB.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);$extensions=['image/jpeg'=>'jpg','image/png'=>'png','application/pdf'=>'pdf'];if(!isset($extensions[$mime]))throw new RuntimeException('Receipt must be JPEG, PNG or PDF.');$folder=__DIR__.'/uploads/fuel';if(!is_dir($folder))mkdir($folder,0750,true);$receipt='uploads/fuel/'.bin2hex(random_bytes(16)).'.'.$extensions[$mime];if(!move_uploaded_file($file['tmp_name'],__DIR__.'/'.$receipt))throw new RuntimeException('Receipt upload failed.');}
   db()->prepare('INSERT INTO fuel_approval(fuel_id,receipt_path) VALUES (?,?)')->execute([$fuelId,$receipt]);v2_event($uid,'vehicle_fuel','Vehicle refueled: '.$v['unit_name'],number_format($liters,2).' L × PHP '.number_format($price,2));redirect('vehicles.php');
  }
  if($action==='maintenance'){
   $issue=trim($_POST['issue']??'');if(!$issue||strlen($issue)>3000)throw new RuntimeException('Enter maintenance details.');db()->prepare('INSERT INTO vehicle_maintenance(vehicle_id,recorded_by,issue_text) VALUES (?,?,?)')->execute([$vehicle,$uid,$issue]);v2_event($uid,'vehicle_maintenance','Maintenance reported: '.$v['unit_name'],$issue);redirect('vehicles.php');
  }
  if($action==='resolve'){
   $id=(int)($_POST['maintenance_id']??0);$q=db()->prepare("UPDATE vehicle_maintenance SET status='resolved' WHERE maintenance_id=? AND status!='resolved'");$q->execute([$id]);if(!$q->rowCount())throw new RuntimeException('Maintenance record not found or already resolved.');v2_event($uid,'vehicle_maintenance','Maintenance marked resolved','Maintenance #'.$id);redirect('vehicles.php');
  }
  throw new RuntimeException('Unknown action.');
 }catch(Throwable $ex){$errors[]=$ex instanceof PDOException?'Database operation failed.':$ex->getMessage();}
}
$vehicles=db()->query('SELECT * FROM vehicle ORDER BY unit_name')->fetchAll();$fuel=db()->query('SELECT f.*,v.unit_name,u.first_name,u.last_name FROM fuel_log f JOIN vehicle v ON v.vehicle_id=f.vehicle_id JOIN user u ON u.user_id=f.recorded_by ORDER BY f.fuel_id DESC LIMIT 60')->fetchAll();$fuel=db()->query('SELECT f.*,v.unit_name,u.first_name,u.last_name,fa.status AS approval_status,fa.receipt_path FROM fuel_log f JOIN vehicle v ON v.vehicle_id=f.vehicle_id JOIN user u ON u.user_id=f.recorded_by LEFT JOIN fuel_approval fa ON fa.fuel_id=f.fuel_id ORDER BY f.fuel_id DESC LIMIT 60')->fetchAll();
$assignments=db()->query('SELECT a.*,v.unit_name,u.first_name,u.last_name FROM vehicle_assignment a JOIN vehicle v ON v.vehicle_id=a.vehicle_id JOIN user u ON u.user_id=a.assigned_user_id ORDER BY a.assignment_id DESC LIMIT 80')->fetchAll();$people=v2_people();
$maintenance=db()->query('SELECT m.*,v.unit_name FROM vehicle_maintenance m JOIN vehicle v ON v.vehicle_id=m.vehicle_id ORDER BY m.maintenance_id DESC LIMIT 60')->fetchAll();
$page_title='Vehicles & Fuel';require __DIR__.'/includes/header.php';?>
<h1>Vehicles, Fuel &amp; Maintenance</h1>
<?php if($admin):?><section class="v2-card"><h2>Register Vehicle</h2><form method="post" class="v2-inline"><?=csrf_field()?><input type="hidden" name="action" value="register"><input name="unit_name" placeholder="Unit name" required><input name="vehicle_type" placeholder="Ambulance / fire / rescue" required><input name="plate_number" placeholder="Plate number"><button>Add Vehicle</button></form></section><?php endif;?><p>Existing vehicle registry with new fuel and maintenance records. Administrative updates are restricted to Admins.</p>
<?php foreach($errors as $err):?><p class="v2-error"><?=e($err)?></p><?php endforeach;?>
<section class="v2-card"><h2>Vehicle Registry</h2><table><thead><tr><th>Unit</th><th>Type</th><th>Plate</th><th>Status</th></tr></thead><tbody><?php foreach($vehicles as $v):?><tr><td><?=e($v['unit_name'])?></td><td><?=e($v['vehicle_type'])?></td><td><?=e($v['plate_number'])?></td><td><?=e($v['status'])?><?php if($admin):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="vehicle_status"><input type="hidden" name="vehicle_id" value="<?=(int)$v['vehicle_id']?>"><select name="status"><?php foreach(['available','in_use','maintenance','out_of_service'] as $status):?><option value="<?=e($status)?>" <?=$v['status']===$status?'selected':''?>><?=e($status)?></option><?php endforeach;?></select><button>Update</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></section>
<?php if($admin):?><div class="v2-grid"><section class="v2-card"><h2>Record Fuel Transaction</h2><form method="post" enctype="multipart/form-data"><?=csrf_field()?><input type="hidden" name="action" value="fuel"><label>Vehicle<select name="vehicle_id"><?php foreach($vehicles as $v):?><option value="<?= (int)$v['vehicle_id']?>"><?=e($v['unit_name'])?></option><?php endforeach;?></select></label><label>Liters<input type="number" name="liters" step="0.01" min="0.01" required></label><label>Price per liter (PHP)<input type="number" name="price" step="0.01" min="0" required></label><label>Odometer (km, optional)<input type="number" name="odometer" step="0.1" min="0"></label><label>Fuel station<input name="station" maxlength="120"></label><label>Receipt (JPEG, PNG, PDF; max 3MB)<input type="file" name="receipt" accept="image/jpeg,image/png,application/pdf"></label><button>Submit Fuel for Approval</button></form></section>
<section class="v2-card"><h2>Report Maintenance</h2><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="maintenance"><label>Vehicle<select name="vehicle_id"><?php foreach($vehicles as $v):?><option value="<?= (int)$v['vehicle_id']?>"><?=e($v['unit_name'])?></option><?php endforeach;?></select></label><label>Issue / work needed<textarea name="issue" maxlength="3000" required></textarea></label><button>Record Maintenance</button></form></section></div><?php endif;?>
<div class="v2-grid"><section class="v2-card"><h2>Fuel Monitoring</h2><?php foreach($fuel as $f):?><article class="v2-entry"><strong><?=e($f['unit_name'])?></strong><p><?=e($f['liters'])?> L × PHP <?=e($f['price_per_liter'])?> = PHP <?=number_format((float)$f['liters']*(float)$f['price_per_liter'],2)?></p><small><?=e($f['fueled_at'])?> · <?=e($f['station'])?> · <?=e($f['approval_status']??'legacy')?></small><?php if(!empty($f['receipt_path'])):?><p><a href="<?=e(url('fuel-receipt.php?id='.(int)$f['fuel_id']))?>" target="_blank" rel="noopener">View receipt</a></p><?php endif;?><?php if($admin&&($f['approval_status']??'')==='pending'):?><?php foreach(['approved'=>'Approve','rejected'=>'Reject'] as $d=>$label):?><form method="post" class="v2-inline"><?=csrf_field()?><input type="hidden" name="action" value="fuel_review"><input type="hidden" name="fuel_id" value="<?=(int)$f['fuel_id']?>"><input type="hidden" name="decision" value="<?=e($d)?>"><button><?=e($label)?></button></form><?php endforeach;?><?php endif;?></article><?php endforeach;?></section>
<section class="v2-card"><h2>Maintenance History</h2><?php foreach($maintenance as $m):?><article class="v2-entry"><div class="v2-between"><strong><?=e($m['unit_name'])?></strong><span class="v2-pill"><?=e($m['status'])?></span></div><p><?=e($m['issue_text'])?></p><small><?=e($m['created_at'])?></small><?php if($admin&&$m['status']!=='resolved'):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="resolve"><input type="hidden" name="maintenance_id" value="<?= (int)$m['maintenance_id']?>"><button>Mark Resolved</button></form><?php endif;?></article><?php endforeach;?></section></div>
<?php if($admin):?><section class="v2-card"><h2>Vehicle Assignments</h2><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="assign"><label>Vehicle<select name="vehicle_id"><?php foreach($vehicles as $v):?><option value="<?=(int)$v['vehicle_id']?>"><?=e($v['unit_name'])?></option><?php endforeach;?></select></label><label>Assigned driver/responder<select name="person_id"><?php foreach($people as $person):?><option value="<?=(int)$person['user_id']?>"><?=e($person['first_name'].' '.$person['last_name'])?></option><?php endforeach;?></select></label><button>Assign Vehicle</button></form></section><?php endif;?>
<section class="v2-card"><h2>Assignment History</h2><?php foreach($assignments as $a):?><?php if($admin||(int)$a['assigned_user_id']===$uid):?><article class="v2-entry"><strong><?=e($a['unit_name'])?></strong> · <?=e($a['first_name'].' '.$a['last_name'])?> · <?=e($a['assigned_at'])?> · <?=empty($a['returned_at'])?'Active':'Returned'?><?php if($admin&&empty($a['returned_at'])):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="release"><input type="hidden" name="assignment_id" value="<?=(int)$a['assignment_id']?>"><button>Record Vehicle Return</button></form><?php endif;?></article><?php endif;?><?php endforeach;?></section>
<?php if($admin):?><section class="v2-card"><h2>Update Maintenance Records</h2><?php foreach($maintenance as $m):?><form method="post" class="v2-entry"><?=csrf_field()?><input type="hidden" name="action" value="maintenance_update"><input type="hidden" name="maintenance_id" value="<?=(int)$m['maintenance_id']?>"><strong><?=e($m['unit_name'])?> · #<?=(int)$m['maintenance_id']?></strong><label>Status<select name="status"><?php foreach(['reported','in_progress','resolved'] as $status):?><option value="<?=e($status)?>" <?=$m['status']===$status?'selected':''?>><?=e($status)?></option><?php endforeach;?></select></label><label>Service date<input type="date" name="service_date"></label><label>Next service<input type="date" name="next_service_date"></label><label>Cost (PHP)<input type="number" name="cost_php" min="0" step="0.01" value="0"></label><label>Work completed / notes<textarea name="resolution_notes"></textarea></label><button>Save Maintenance Update</button></form><?php endforeach;?></section><?php endif;?>
<?php require __DIR__.'/includes/footer.php';?>
